# OfficeHQ

A full-stack office-management web application.

- **Front end:** Angular single-page app (standalone components, lazy routes), built into
  `src/main/resources/static`.
- **Back end:** Spring Boot with Spring MVC `@RestController` endpoints, on an in-memory H2 database
  with Flyway migrations run on boot.

## Build and run

```
bin/build              # build the SPA and package one runnable jar
PORT=3000 bin/start    # start the app (serves the SPA + REST on $PORT)
bin/stop               # stop it
```

Readiness: `GET /actuator/health`.

## Tests

End-to-end tests use Playwright (in `e2e/`) and bind to `data-testid`:

```
bin/e2e                # build, start, run the specs in e2e/specs, then stop
```
{
  "data_sets": []
}<?xml version="1.0" encoding="UTF-8"?>
<!--
  OfficeHQ — a Spring Boot app. Domain REST endpoints are Spring @RestController methods. Spring
  serves the Angular SPA (static/), with H2 + Flyway + Actuator.
-->
<project xmlns="http://maven.apache.org/POM/4.0.0"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd">
  <modelVersion>4.0.0</modelVersion>

  <!-- Standard Spring Boot app parent (4.1.0). -->
  <parent>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-parent</artifactId>
    <version>4.1.0</version>
    <relativePath/>
  </parent>

  <groupId>net.officefloor.hq</groupId>
  <artifactId>officehq-app</artifactId>
  <version>0.0.1-SNAPSHOT</version>
  <packaging>jar</packaging>

  <properties>
    <java.version>17</java.version>
    <node.version>v22.12.0</node.version>
    <npm.version>10.9.0</npm.version>
  </properties>

  <dependencies>
    <!-- Domain endpoints are Spring @RestController methods. -->
    <!-- Spring Boot hosts: web (serves the SPA from static/ + hosts the HTTP server),
         data-jpa (H2 access for services), actuator (health probe). -->
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-data-jpa</artifactId>
    </dependency>
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-actuator</artifactId>
    </dependency>
    <!-- Bean Validation provider (Hibernate Validator) — REST bind + @Valid. -->
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-validation</artifactId>
    </dependency>

    <!-- In-memory H2 + Flyway schema migrations on boot (Spring-managed). -->
    <dependency>
      <groupId>com.h2database</groupId>
      <artifactId>h2</artifactId>
      <scope>runtime</scope>
    </dependency>
    <dependency>
      <groupId>org.flywaydb</groupId>
      <artifactId>flyway-core</artifactId>
    </dependency>
    <!-- REQUIRED under Spring Boot 4: FlywayAutoConfiguration was extracted from
         spring-boot-autoconfigure into this module. Without it, flyway-core is on the classpath but
         migrations NEVER run on boot (silently — no error, the table is just missing). Version is
         managed by the parent BOM. flyway-core 12.x has H2 support built in, so no
         flyway-database-h2 module is needed. -->
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-flyway</artifactId>
    </dependency>

    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-test</artifactId>
      <scope>test</scope>
    </dependency>
  </dependencies>

  <build>
    <plugins>
      <!-- Build the Angular SPA into src/main/resources/static so Spring serves it
           (angular.json -> outputPath {base: ../resources/static, browser: ''}). -->
      <plugin>
        <groupId>com.github.eirslett</groupId>
        <artifactId>frontend-maven-plugin</artifactId>
        <version>1.15.1</version>
        <configuration>
          <workingDirectory>src/main/frontend</workingDirectory>
          <nodeVersion>${node.version}</nodeVersion>
          <npmVersion>${npm.version}</npmVersion>
        </configuration>
        <executions>
          <execution>
            <id>install-node-and-npm</id>
            <goals><goal>install-node-and-npm</goal></goals>
            <phase>generate-resources</phase>
          </execution>
          <execution>
            <id>npm-ci</id>
            <goals><goal>npm</goal></goals>
            <phase>generate-resources</phase>
            <configuration><arguments>ci</arguments></configuration>
          </execution>
          <execution>
            <id>npm-build</id>
            <goals><goal>npm</goal></goals>
            <phase>generate-resources</phase>
            <configuration><arguments>run build</arguments></configuration>
          </execution>
        </executions>
      </plugin>

      <!-- Standard Spring Boot executable jar (main = the @SpringBootApplication class). -->
      <plugin>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-maven-plugin</artifactId>
        <configuration>
          <mainClass>net.officefloor.hq.app.Application</mainClass>
        </configuration>
      </plugin>
    </plugins>
  </build>
</project>
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
package net.officefloor.hq.app;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Spring Boot host: serves the SPA from static/, with H2 + Flyway (schema migrated on boot) and
 * Actuator. Domain REST endpoints, @Service/@Repository beans and migrations are added under
 * src/main/java and src/main/resources.
 */
@SpringBootApplication
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.resource.PathResourceResolver;

/**
 * Serve the SPA from static/ with a deep-link fallback: an unknown, non-API path returns
 * index.html so a browser refresh on a client route works. OfficeFloor REST routes and Spring
 * endpoints are matched first; only unmatched, non-{@code api/} paths fall through to the SPA.
 * TODO: confirm the API path prefix used by the OfficeFloor routes ("api/" assumed here).
 */
@Configuration
public class SpaConfig implements WebMvcConfigurer {

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        registry.addResourceHandler("/**")
                .addResourceLocations("classpath:/static/")
                .resourceChain(true)
                .addResolver(new PathResourceResolver() {
                    @Override
                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
                        if (resourcePath.startsWith("api/")) {
                            return null; // let the API handle / 404 it
                        }
                        Resource requested = location.createRelative(resourcePath);
                        return (requested.exists() && requested.isReadable())
                                ? requested
                                : location.createRelative("index.html");
                    }
                });
    }
}
package net.officefloor.hq.app;

import java.util.Map;
import org.springframework.context.annotation.Profile;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
 * ARRANGE data; they ASSERT only through the UI.
 */
@Profile("e2e")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private final Audit audit;

    public TestSupportController(Audit audit) {
        this.audit = audit;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    public void reset() {
        audit.clear();
        // TODO: TRUNCATE the domain tables that currently exist (inject a JdbcTemplate/repo).
    }

    /**
     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
     */
    @PostMapping("/seed")
    public void seed(@RequestBody Map<String, Object> fixture) {
        // TODO: insert rows for the fixture.
    }

    /**
     * Read back what is stored, in the same shape and with the same field names the fixtures use,
     * so the app's test data sets can be checked (AGENTS.md §4.3, §4.4).
     */
    @GetMapping("/fixture")
    public Map<String, Object> fixture() {
        // TODO: return each collection that exists, e.g. {"clients": [...], "invoices": [...]}.
        return Map.of();
    }
}
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';

// The app's wiring: the router and the HTTP client.
export const appConfig: ApplicationConfig = {
  providers: [provideBrowserGlobalErrorListeners(), provideRouter(routes), provideHttpClient()],
};
import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
];
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { Component } from '@angular/core';

// The base home page (empty). A page is an Angular component like this one, plus one entry in
// app.routes.ts.
@Component({
  selector: 'app-home',
  template: `<p data-testid="home-empty">Nothing here yet.</p>`,
})
export class Home {}
#!/usr/bin/env bash
# Build the whole app into ONE runnable jar: the Maven build compiles the front-end
# (frontend-maven-plugin) into src/main/resources/static, then packages the Spring Boot app
# (spring-boot repackage, main net.officefloor.hq.app.Application) into target/*.jar.
set -euo pipefail
cd "$(dirname "$0")/.."

# `clean` first so removed sources (e.g. a deleted route .yml or class) can't linger in
# target/classes and get baked into the jar.
exec ./mvnw -q -DskipTests clean package
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints; the `e2e` profile enables the /__test__ seed endpoint. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid
#!/usr/bin/env bash
# Stop the app and free $PORT. Kills the JVM (in-memory H2 dies with it = clean reset).
# IDEMPOTENT: exit 0 whether or not anything was running.
set -uo pipefail
cd "$(dirname "$0")/.."

if [ -f .run/app.pid ]; then
  kill "$(cat .run/app.pid)" 2>/dev/null || true
  rm -f .run/app.pid
fi
# Backstop: free the port if something is still bound (needs fuser; ignore if absent).
[ -n "${PORT:-}" ] && fuser -k "${PORT}/tcp" 2>/dev/null || true
exit 0
// Per-test data setup (AGENTS.md §4). Each test RESETS then SEEDS via the app's /__test__
// endpoints — this is Arrange, not Assert. Tests still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: reset and seed are the Arrange for EVERY test, so they are a hard precondition — if
// either does not return 2xx the data is not in the state the test assumes, and a silent failure
// would surface later as confusing, misattributed assertion failures. We throw here so the break is
// attributed to the seed.
//
// TEST-DATA CONTRACT (AGENTS.md §4.4): before the first test seeds anything, the app's test data
// sets (.run/fixture-contract.json — data only) are checked: reset, seed, read back with
// GET /__test__/fixture, and every seeded field must come back with the same value. That catches a
// seed endpoint that stopped storing a field some data set relies on.
//   SEED_CONTRACT=enforce (default)  a failure fails the test that triggered the check
//   SEED_CONTRACT=report             record the result, never fail a test
//   SEED_CONTRACT=off                skip
import { request, type APIRequestContext, type APIResponse } from '@playwright/test';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;
// Playwright runs from e2e/, so the app's .run/ is one level up (as audit.ts assumes).
const RUN_DIR = process.env.RUN_DIR ?? resolve(process.cwd(), '..', '.run');
const CONTRACT_FILE = process.env.FIXTURE_CONTRACT ?? resolve(RUN_DIR, 'fixture-contract.json');
const RESULT_FILE = process.env.SEED_CONTRACT_RESULT ?? resolve(RUN_DIR, 'seed-contract-result.json');
const MODE = (process.env.SEED_CONTRACT ?? 'enforce').toLowerCase();

async function must(res: Promise<APIResponse>, what: string): Promise<APIResponse> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
  return r;
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await checkContractOnce(api);
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

// ---- test-data contract check --------------------------------------------------------------

type DataSet = { name: string; test: string; fixture: Record<string, unknown> };
type Result = { contract_sha256: string; run: number; ok: boolean; checked: number; failures: string[] };

let checked: Promise<Result | null> | null = null;

async function checkContractOnce(api: APIRequestContext): Promise<void> {
  if (MODE === 'off' || !existsSync(CONTRACT_FILE)) return;
  // Once per Playwright run. A worker restarts after a failed test, so the result file is the
  // marker, not just this module's state — keyed by the contract AND the run (the worker's parent
  // is the Playwright runner). A later `bin/e2e` is a new run and checks again, so a fix to the
  // seed endpoint is seen at once instead of the previous run's failure being re-reported.
  checked ??= (async () => {
    const raw = readFileSync(CONTRACT_FILE, 'utf8');
    const sha = createHash('sha256').update(raw).digest('hex');
    if (existsSync(RESULT_FILE)) {
      const prev = JSON.parse(readFileSync(RESULT_FILE, 'utf8')) as Result;
      if (prev.contract_sha256 === sha && prev.run === process.ppid) return prev;
    }
    const sets = (JSON.parse(raw).data_sets ?? []) as DataSet[];
    const res: Result = { contract_sha256: sha, run: process.ppid, ok: true, checked: sets.length, failures: [] };
    if (sets.length) res.failures = await checkSets(api, sets);
    res.ok = res.failures.length === 0;
    mkdirSync(dirname(RESULT_FILE), { recursive: true });
    writeFileSync(RESULT_FILE, JSON.stringify(res, null, 2));
    return res;
  })();
  const res = await checked;
  if (res && !res.ok && MODE === 'enforce') {
    throw new Error(`test-data contract: ${res.failures.length} problem(s) (AGENTS.md §4.4)\n`
      + res.failures.slice(0, 20).join('\n'));
  }
}

class ReadBackMissing extends Error {}

async function readBack(api: APIRequestContext): Promise<unknown> {
  const r = await must(api.get('/__test__/fixture'), 'GET /__test__/fixture');
  // An unimplemented route typically falls through to the SPA's index.html with a 200.
  if (!(r.headers()['content-type'] ?? '').includes('json')) {
    throw new ReadBackMissing('GET /__test__/fixture does not return JSON — implement the read-back '
      + '(AGENTS.md §4.3) so the test data sets can be checked');
  }
  return r.json();
}

async function checkSets(api: APIRequestContext, sets: DataSet[]): Promise<string[]> {
  const out: string[] = [];
  for (const set of sets) {
    const where = `  in the data set of "${set.test}" (${set.name})`;
    try {
      await must(api.post('/__test__/reset'), 'POST /__test__/reset');
      await must(api.post('/__test__/seed', { data: set.fixture }), 'POST /__test__/seed');
      for (const f of compare(set.fixture, await readBack(api), '')) out.push(`the seed did not keep ${f}\n${where}`);
    } catch (e) {
      if (e instanceof ReadBackMissing) return [e.message];     // one cause, not one per fixture
      out.push(`${(e as Error).message}\n${where}`);
    }
    if (out.length >= 50) break;
  }
  try {
    // A reset must really empty the data; an endpoint that echoes its input would not.
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    if (!isEmpty(await readBack(api))) out.push('GET /__test__/fixture still returns rows after POST /__test__/reset');
  } catch (e) {
    out.push((e as Error).message);
  }
  return out;
}

// ---- comparison (AGENTS.md §4.4: numbers by value, dates as yyyy-mm-dd, rows by id) -----------

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const NUMERIC = /^-?\d+(\.\d+)?$/;
const show = (v: unknown) => (v === undefined ? '<missing>' : JSON.stringify(v));

function sameScalar(sent: unknown, got: unknown): boolean {
  if (sent === got) return true;
  if (got === undefined || got === null) return sent === null;
  if (typeof sent === 'number' || (typeof sent === 'string' && NUMERIC.test(sent))) {
    const a = Number(sent), b = Number(got);
    if (!Number.isNaN(a) && !Number.isNaN(b)) return Math.abs(a - b) < 1e-9;
  }
  if (typeof sent === 'string' && DATE.test(sent) && typeof got === 'string') return got.slice(0, 10) === sent;
  if (typeof sent === 'boolean') return got === sent || String(got) === String(sent);
  return false;
}

function compare(sent: unknown, got: unknown, path: string): string[] {
  if (Array.isArray(sent)) {
    if (!Array.isArray(got)) return [`${path || 'the data'} (sent a list, read back ${show(got)})`];
    const out: string[] = [];
    for (const row of sent) {
      if (row && typeof row === 'object' && !Array.isArray(row) && 'id' in row) {
        const id = (row as { id: unknown }).id;
        const match = got.find((g) => g && typeof g === 'object' && sameScalar(id, (g as { id?: unknown }).id));
        if (!match) out.push(`${path}[id=${id}] (row missing from the read-back)`);
        else out.push(...compare(row, match, `${path}[id=${id}]`));
      } else if (!got.some((g) => compare(row, g, path).length === 0)) {
        out.push(`${path}[] ${show(row)} (no matching row in the read-back)`);
      }
    }
    return out;
  }
  if (sent && typeof sent === 'object') {
    if (!got || typeof got !== 'object' || Array.isArray(got)) return [`${path || 'the data'} (read back ${show(got)})`];
    const out: string[] = [];
    for (const [k, v] of Object.entries(sent)) {
      out.push(...compare(v, (got as Record<string, unknown>)[k], path ? `${path}.${k}` : k));
    }
    return out;
  }
  return sameScalar(sent, got) ? [] : [`${path} (sent ${show(sent)}, read back ${show(got)})`];
}

function isEmpty(v: unknown): boolean {
  if (v === null || v === undefined) return true;
  if (Array.isArray(v)) return v.length === 0;
  if (typeof v === 'object') return Object.values(v as object).every((x) => !Array.isArray(x) || x.length === 0);
  return false;
}

